import java.util.List;

class Bounds {
    // one bound: extends, even for an interface
    static <T extends Comparable<T>> T maxOf2(T a, T b) {
        return a.compareTo(b) >= 0 ? a : b;
    }

    // two bounds with &: the class (if any) must come first
    static <T extends CharSequence & Comparable<T>> T shortest(List<T> items) {
        T best = items.get(0);
        for (T item : items) {
            if (item.length() < best.length()) best = item;
        }
        return best;
    }

    // no way to say "not null": T may always be null
    static <T> T firstOrThrow(List<T> items) {
        return items.get(0);   // could be null
    }
}

kotlin.src:
// one bound: a colon
fun <T : Comparable<T>> maxOf2(a: T, b: T): T = if (a >= b) a else b

// two bounds: a where clause, in any order, at most one class
fun <T> shortest(items: List<T>): T where T : CharSequence, T : Comparable<T> {
    var best = items[0]
    for (item in items) {
        if (item.length < best.length) best = item
    }
    return best
}

// T : Any rules out nullable type arguments
fun <T : Any> firstOrThrow(items: List<T>): T = items[0]   // never null

